  for (let k = 0; k < SB.length; k++) vgApplyEffect(SB[k]);
  for (let k = 0; k < ME.length; k++) vgApplyEffect(ME[k]);
  for (let k = 0; k < SB.length; k++) vgApplyEffect(SB[k]);
  for (let k = 0; k < NM.length; k++) vgApplyEffect(NM[k]);
