    // avatar wall > stepBack
    if (t_avatar.n !== 0 && t_wall.n !== 0) {
      if (t_avatar.n <= t_wall.n) { for (let k = 0; k < t_avatar.n; k++) { const i = t_avatar.live[k]; vgCollectType(t_avatar, i, t_wall); const nc = vgCand.length;
        for (let q = 0; q < nc; q++) { const j = vgCand[q]; if (!t_avatar.killed[i]) { VG_EFFECTS.stepBack(t_avatar, i, t_wall, j, undefined); } } } }
      else { for (let k = 0; k < t_wall.n; k++) { const i = t_wall.live[k]; vgCollectType(t_wall, i, t_avatar); const nc = vgCand.length;
        for (let q = 0; q < nc; q++) { const j = vgCand[q]; if (!t_avatar.killed[j]) { VG_EFFECTS.stepBack(t_avatar, j, t_wall, i, undefined); } } } }
    }
    // ---- stepBack pass 2 ----
    // avatar wall > stepBack
    if (t_avatar.n !== 0 && t_wall.n !== 0) {
      if (t_avatar.n <= t_wall.n) { for (let k = 0; k < t_avatar.n; k++) { const i = t_avatar.live[k]; vgCollectType(t_avatar, i, t_wall); const nc = vgCand.length;
        for (let q = 0; q < nc; q++) { const j = vgCand[q]; if (!t_avatar.killed[i]) { VG_EFFECTS.stepBack(t_avatar, i, t_wall, j, undefined); } } } }
      else { for (let k = 0; k < t_wall.n; k++) { const i = t_wall.live[k]; vgCollectType(t_wall, i, t_avatar); const nc = vgCand.length;
        for (let q = 0; q < nc; q++) { const j = vgCand[q]; if (!t_avatar.killed[j]) { VG_EFFECTS.stepBack(t_avatar, j, t_wall, i, undefined); } } } }
    }
    // ---- non-move effects ----
